/* Instrument v0.1, the chat. Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json),
   on :root: paint, so nothing in the transcript moves when this applies or reloads. Every colour is the
   theme's ink (--agent-text) mixed into its page (--agent-page-bg) at a multiple of 4%, so it holds over
   Instrument, Instrument Light and any theme of your own. Text: ink 100, muted 84, dim 68. Fills: card
   4, prompt 8, card line 12. Links are the ink: colour is for status only. */
:root {
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 84%, var(--agent-page-bg));
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 68%, var(--agent-page-bg));
  --cv-link: var(--agent-text);
  --agent-link: var(--agent-text);
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 4%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --cv-user-bubble-edge: transparent;
  /* The container corner: control 8 + inset 4. */
  --cv-user-bubble-radius: 12px;

  /* Pending (cmux #46846): every page-drawn menu and popover on the same ladder: a 12 px container
     corner (control 8 + inset 4), 4 px padding, 28 px rows with an 8 px hover corner on an 8% fill,
     12% border and separator inset 8 px, labels at the control size in the regular weight,
     shortcuts and subtitles in the dim 68% mix, disabled at half opacity, one quiet shadow. */
  --menu-radius: 12px;
  --menu-padding: 4px;
  --menu-border: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-shadow: 0 2px 6px rgb(0 0 0 / 0.11);
  --menu-row-height: 28px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --menu-hover-radius: 8px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --menu-separator-inset: 8px;
  --menu-label-color: var(--agent-text);
  --menu-label-weight: 400;
  --menu-label-size: var(--text-control);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 68%, var(--agent-page-bg));
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 68%, var(--agent-page-bg));
  --menu-disabled-opacity: 0.5;
}
